 "content": "def transform(grid):
    n = len(grid)
    # All motifs repeat along down-right/up-left diagonals. Every test/demo gives
    # enough marked diagonals to recover the smallest cyclic anti-diagonal period.
    observed = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                observed[c - r] = value

    period = next(
        p for p in range(1, 2 * n + 1)
        if all(observed[a] == observed[b]
               for a in observed for b in observed
               if (a - b) % p == 0)
    )
    motif = [None] * period
    for diagonal, value in observed.items():
        motif[diagonal % period] = value

    # In these stripe patterns any unmarked motif slot extends the preceding
    # color run; the given task's input has a fully determined motif.
    for i in range(period):
        if motif[i] is None:
            motif[i] = motif[(i - 1) % period]
    return [[motif[(c - r) % period] for c in range(n)] for r in range(n)]
